class PathFixerApp extends foundry.applications.api.ApplicationV2 {
    static DEFAULT_OPTIONS = {
        id: "path-fixer",
        window: { title: "Path String Fixer", resizable: true },
        position: { width: 860 },
    };

    #search = "";
    #replace = "";
    #results = null;
    #scanning = false;
    #replacing = false;
    #cancelled = false;

    async _prepareContext() {
        return {
            search: this.#search,
            replace: this.#replace,
            results: this.#results,
            scanning: this.#scanning,
            replacing: this.#replacing,
        };
    }

    async _renderHTML(context) {
        const div = document.createElement("div");
        div.innerHTML = this.#buildHTML(context);
        return div;
    }

    _replaceHTML(result, content) {
        content.innerHTML = result.innerHTML;
    }

    _onRender() {
        const el = this.element;
        el.querySelector("#pf-find")?.addEventListener("click", () => this.#onFind());
        el.querySelector("#pf-cancel")?.addEventListener("click", () => { this.#cancelled = true; });
        el.querySelector("#pf-replace-btn")?.addEventListener("click", () => this.#onReplace());
    }

    #buildHTML(ctx) {
        return `
            <div style="padding:8px;">
                <div class="form-group">
                    <label>Find</label>
                    <div class="form-fields">
                        <input type="text" id="pf-search" value="${ctx.search}"
                            placeholder="modules/pf2e-kingmaker-tools/img/">
                    </div>
                </div>
                <div class="form-group">
                    <label>Replace</label>
                    <div class="form-fields">
                        <input type="text" id="pf-replace" value="${ctx.replace}"
                            placeholder="modules/pf2e-kingmaker-tools/art/">
                    </div>
                </div>
                <div class="form-group">
                    <label></label>
                    <div class="form-fields">
                        ${ctx.scanning
                            ? `<button type="button" id="pf-cancel">Cancel</button>`
                            : `<button type="button" id="pf-find">Find</button>`
                        }
                    </div>
                </div>
                ${this.#buildResults(ctx)}
            </div>
        `;
    }

    #buildResults(ctx) {
        if (!ctx.results) return "";
        if (ctx.results.length === 0) return `<p class="hint">No matches found.</p>`;

        const existCount = ctx.results.filter(r => r.exists).length;
        const rows = ctx.results.map(row => {
            const icon = row.exists
                ? `<i class="fa-solid fa-check" style="color:var(--color-level-success)"></i>`
                : `<i class="fa-solid fa-xmark" style="color:var(--color-level-error)"></i>`;
            return `<tr>
                <td style="word-break:break-all;">${row.original}</td>
                <td style="word-break:break-all;">${row.replacement}</td>
                <td style="text-align:center;">${icon}</td>
            </tr>`;
        }).join("");

        return `
            <p class="hint">
                Found <strong>${ctx.results.length}</strong> unique paths —
                <strong>${existCount}</strong> replacements exist,
                <strong>${ctx.results.length - existCount}</strong> do not.
            </p>
            <div style="max-height:420px; overflow-y:auto;">
                <table>
                    <thead>
                        <tr>
                            <th>Original Path</th>
                            <th>New Path</th>
                            <th style="width:60px; text-align:center;">Exists</th>
                        </tr>
                    </thead>
                    <tbody>${rows}</tbody>
                </table>
            </div>
            ${existCount > 0 ? `
                <div class="form-group" style="margin-top:8px;">
                    <label></label>
                    <div class="form-fields">
                        <button type="button" id="pf-replace-btn" ${ctx.replacing ? "disabled" : ""}>
                            ${ctx.replacing ? "Replacing..." : `Replace Existing (${existCount} paths)`}
                        </button>
                    </div>
                </div>
            ` : ""}
        `;
    }

    async #onFind() {
        const el = this.element;
        const search = el.querySelector("#pf-search").value.trim();
        const replace = el.querySelector("#pf-replace").value.trim();
        if (!search) { ui.notifications.warn("Enter a search string."); return; }
        this.#search = search;
        this.#replace = replace;
        this.#scanning = true;
        this.#cancelled = false;
        this.#results = null;
        this.render();
        this.#results = await this.#scan(search, replace);
        this.#scanning = false;
        this.render();
    }

    async #onReplace() {
        this.#replacing = true;
        this.render();
        const count = await this.#applyReplacements();
        this.#replacing = false;
        ui.notifications.info(`Path Fixer: updated ${count} document(s).`);
        this.#results = await this.#scan(this.#search, this.#replace);
        this.render();
    }

    #collectStrings(obj, search, out = new Set()) {
        if (typeof obj === "string") {
            if (obj.includes(search)) out.add(obj);
        } else if (Array.isArray(obj)) {
            for (const v of obj) this.#collectStrings(v, search, out);
        } else if (obj && typeof obj === "object") {
            for (const v of Object.values(obj)) this.#collectStrings(v, search, out);
        }
        return out;
    }

    async #scan(search, replace) {
        const unique = new Set();
        const collections = [game.scenes, game.actors, game.items, game.journal,
                             game.tables, game.playlists, game.macros, game.cards];
        for (const col of collections) {
            for (const doc of col) this.#collectStrings(doc.toObject(), search, unique);
        }
        const rows = [];
        for (const original of unique) {
            if (this.#cancelled) return null;
            const replacement = original.replaceAll(search, replace);
            const exists = await this.#fileExists(replacement);
            rows.push({ original, replacement, exists });
        }
        rows.sort((a, b) => a.original.localeCompare(b.original));
        return rows;
    }

    async #fileExists(path) {
        try {
            const res = await fetch(path, { method: "HEAD" });
            return res.ok;
        } catch { return false; }
    }

    async #applyReplacements() {
        const toReplace = this.#results?.filter(r => r.exists) ?? [];
        if (!toReplace.length) return 0;
        const collections = [game.scenes, game.actors, game.items, game.journal,
                             game.tables, game.playlists, game.macros, game.cards];
        let updated = 0;
        for (const col of collections) {
            for (const doc of col) {
                let raw = JSON.stringify(doc.toObject());
                let changed = false;
                for (const { original, replacement } of toReplace) {
                    if (raw.includes(original)) { raw = raw.replaceAll(original, replacement); changed = true; }
                }
                if (changed) {
                    await doc.update(JSON.parse(raw));
                    updated++;
                    console.log(`[path-fixer] Updated: ${doc.documentName} "${doc.name}"`);
                }
            }
        }
        return updated;
    }
}

const existing = Object.values(ui.windows).find(w => w.id === "path-fixer");
if (existing) existing.bringToTop();
else new PathFixerApp().render({ force: true });
